  "knapsack": {
    "python": "def solve(weights, values, capacity):\n    best = [0] * (capacity + 1)\n    for weight, value in zip(weights, values):\n        # Descending capacities prevent taking this item twice.\n        for room in range(capacity, weight - 1, -1):\n            best[room] = max(best[room], best[room-weight] + value)\n    return best[capacity]\n",
    "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\nint solve(vector<int> weights, vector<int> values, int capacity) {\n    vector<int> best(capacity+1);\n    for(int i=0;i<(int)weights.size();i++)\n        for(int room=capacity;room>=weights[i];room--)\n            best[room]=max(best[room],best[room-weights[i]]+values[i]);\n    return best[capacity];\n}\n",
    "java": "import java.util.*;\n\nclass Algorithm {\n    static int solve(int[] weights, int[] values, int capacity) {\n        int[] best=new int[capacity+1];\n        for(int i=0;i<weights.length;i++)\n            for(int room=capacity;room>=weights[i];room--)\n                best[room]=Math.max(best[room],best[room-weights[i]]+values[i]);\n        return best[capacity];\n    }\n}\n"
  },
  "coin-change": {
    "python": "def solve(values, amount):\n    best = [0] + [amount + 1] * amount\n    for total in range(1, amount + 1):\n        for coin in values:\n            if coin <= total:\n                best[total] = min(best[total], best[total-coin] + 1)\n    return best[amount] if best[amount] <= amount else -1\n",
    "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\nint solve(vector<int> values, int amount) {\n    vector<int> best(amount+1,amount+1); best[0]=0;\n    for(int total=1;total<=amount;total++)\n        for(int coin:values) if(coin<=total)\n            best[total]=min(best[total],best[total-coin]+1);\n    return best[amount]>amount ? -1 : best[amount];\n}\n",
    "java": "import java.util.*;\n\nclass Algorithm {\n    static int solve(int[] values, int amount) {\n        int[] best=new int[amount+1]; Arrays.fill(best,amount+1); best[0]=0;\n        for(int total=1;total<=amount;total++)\n            for(int coin:values) if(coin<=total)\n                best[total]=Math.min(best[total],best[total-coin]+1);\n        return best[amount]>amount ? -1 : best[amount];\n    }\n}\n"
  },
